def oracle_replay(topology, events, infinity, poison=False, hold_down=None):
    """Full expected replay: one list per timeline entry of recorded rounds.

    Plain entries are ``[view, ...]``; hold-down entries are
    ``([view, ...], [public_timers, ...])``.  The baseline builds from a
    direct-only round 0; event entries inherit the previous converged view,
    build failure round zero (with the transitive hold-down closure when
    hold-down is positive), then iterate.
    """
    nodes, full = _adjacency(topology)

    def fold_state(down, disabled):
        active = {node: {} for node in nodes}
        for router in nodes:
            if router in down:
                continue
            for neighbor, weight in full[router].items():
                pair = (router, neighbor) if router < neighbor \
                    else (neighbor, router)
